    // 上半分左側に縦棒が残るのが5、右側に寄るのが3なので先に形状で分離する。
    const leftMid=(()=>{
      let hit=0,total=0;
      for(let y=3;y<8;y++)for(let x=0;x<4;x++){hit+=glyph[y*12+x];total++;}
      return total?hit/total:0;
    })();
    const rightMid=(()=>{
      let hit=0,total=0;
      for(let y=3;y<8;y++)for(let x=8;x<12;x++){hit+=glyph[y*12+x];total++;}
      return total?hit/total:0;
    })();
